'use strict';
// Presentation layer only. Existing workflow state and integration contracts are unchanged.
const workspaceLabels={home:'My workspace',patients:'Patients',record:'Patient record',C:'Consultation',documents:'Documents',N:'Document editor',review:'Review queue',F:'Forms & assessments',T:'Tasks & handovers',E:'Patient context',I:'EPR handoff',NHS:'Governance',extensions:'Extensions',connections:'Connections',organisation:'Organisation',settings:'Settings',catalogue:'Capability library',delivery:'Delivery plan',loops:'Implementation loops'};
let patientQuery='',documentFilter='all',taskFilter='open',taskOwner='all';
let mobileNavigationOpen=false;
const workspaceMobileQuery=window.matchMedia?.('(max-width:760px)');
function allDocumentRows(){ensurePatientState();return demoPatients.filter(p=>state.patientRecords[p.id].note.trim()).map(p=>({patient:p,record:state.patientRecords[p.id]}));}
function pendingReviewCount(){ensurePatientState();return demoPatients.reduce((n,p)=>{const r=state.patientRecords[p.id];return n+Number(!!r.note.trim()&&!r.signed)+Number(!!r.formData&&!r.formApproval)},0);}
function openPatient(id,target='record'){selectPatient(id);nav(target);}
function uiNav(id,symbol,title,countValue){const active=route===id||(id==='patients'&&route==='record')||(id==='documents'&&route==='N');return `<button class="${active?'active':''}" ${active?'aria-current="page"':''} onclick="nav('${id}')">${icon(symbol)}<span>${title}</span>${countValue?`<span class="nav-count">${countValue}</span>`:''}</button>`;}
renderSidebar=function(){document.getElementById('sidebar').innerHTML=`<button class="navigation-close" onclick="closeWorkspaceNavigation()" aria-label="Close navigation">Close navigation ×</button><a class="brand product-brand" href="#home" onclick="event.preventDefault();nav('home')" aria-label="DeepSynaps Clinical Admin workspace"><img class="real-logo" src="assets/deepsynaps-logo.svg" alt=""><div><strong>DeepSynaps</strong><small>CLINICAL ADMIN</small></div></a><button class="org org-button" onclick="nav('organisation')"><span class="organisation-initial">OH</span><span><strong>Oxford Health</strong><small>NHS Foundation Trust</small><em>Workspace configuration</em></span></button><nav aria-label="Main navigation"><div class="nav-label">DAILY WORK</div>${uiNav('home','grid','My workspace')}${uiNav('patients','people','Patients')}${uiNav('review','check','Review queue',pendingReviewCount())}${uiNav('T','calendar','Tasks & handovers',state.tasks.filter(t=>!t.done).length)}<div class="nav-label">CLINICAL WORKSPACE</div>${uiNav('C','mic','Consultation')}${uiNav('documents','file','Documents')}${uiNav('F','form','Forms & assessments')}${uiNav('E','book','Patient context')}<div class="nav-label">MANAGE</div>${uiNav('extensions','spark','DeepSynaps extensions')}${uiNav('connections','link','Connections')}${uiNav('settings','settings','Settings')}</nav><div class="side-bottom"><button class="workspace-service" onclick="nav('connections')"><span class="status-dot"></span><span>Clinical OS <strong>Not connected</strong></span>${icon('arrow')}</button><button class="profile workspace-profile" onclick="showWorkspaceProfile()"><span class="avatar">JM</span><span>Dr Jamie Morgan<small>Example clinician</small></span>${icon('settings')}</button></div>`;};
function showWorkspaceProfile(){modal('Workspace identity',`<p><strong>Dr Jamie Morgan</strong> is a fictional clinician used while the product interface is being developed.</p><p>Clinical OS sign-in, verified staff roles and organisation membership are not connected yet. The selected workspace is configured for the proposed Oxford Health deployment.</p>`,`<button onclick="closeModal()">Close</button><button class="primary" onclick="closeModal();nav('connections')">View connection requirements</button>`);}
function workspaceTopbar(){return `<button class="mobile-menu top-icon" id="navigation-toggle" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false" onclick="openWorkspaceNavigation()">${icon('menu')}</button><div class="breadcrumb">Clinical Admin <span class="crumb-separator">/</span><b>${esc(workspaceLabels[route]||'Workspace')}</b></div><button class="workspace-search" onclick="openWorkspaceSearch()">${icon('search')}<span>Find a patient or workspace…</span><kbd>⌘ K</kbd></button><button class="top-icon" onclick="nav('review')" aria-label="Review queue, ${pendingReviewCount()} items">${icon('check')}${pendingReviewCount()?`<span class="header-count">${pendingReviewCount()}</span>`:''}</button><button class="top-icon theme-control" onclick="toggleTheme()" aria-label="Switch to ${state.product.theme==='light'?'dark':'light'} theme">${state.product.theme==='light'?'☾':'☀'}</button>`;}
function pageHeading(title,subtitle,actions=''){return head(title,subtitle,actions,'OXFORD HEALTH / CLINICAL WORKSPACE');}
function metric(label,value,detail,to,accent=false){return `<button class="stat ${accent?'first':''}" onclick="nav('${to}')"><span class="stat-top">${label}${icon('arrow')}</span><strong class="stat-value">${value}</strong><span class="stat-bottom">${detail}</span></button>`;}
home=function(){const docs=allDocumentRows();const drafts=docs.filter(d=>!d.record.signed).length;const openTasks=state.tasks.filter(t=>!t.done);return pageHeading('My workspace','Appointments, documentation and follow-up in one place.',`<button onclick="openWorkspaceSearch()">${icon('search')} Find a patient</button><button class="primary" onclick="chooseConsultation()">${icon('plus')} Start consultation</button>`)+`<div class="workspace-day"><span>${icon('calendar')} Tuesday, 13 October 2026 <span class="pill grey">Example clinic</span></span><span>${esc(service().name)} <span class="divider-dot">·</span> ${esc(state.product.team)}</span></div><div class="stats workspace-stats">${metric('Scheduled appointments',demoPatients.length,'View the clinic list','patients',true)}${metric('Awaiting review',pendingReviewCount(),'Documents and forms','review')}${metric('Open team tasks',openTasks.length,'Assigned work and follow-up','T')}${metric('Draft documents',drafts,'Continue where you left off','documents')}</div><div class="workspace-grid"><section><div class="panel clinic-panel"><div class="panel-head"><div><h2>Clinic list</h2><p>Choose a patient to open their workspace.</p></div><button class="text-btn" onclick="nav('patients')">All patients ${icon('arrow')}</button></div><div class="clinic-table-wrap"><table class="clinic-table"><thead><tr><th scope="col">Time</th><th scope="col">Patient</th><th scope="col">Appointment</th><th scope="col">Documentation</th><th scope="col"><span class="sr-only">Open</span></th></tr></thead><tbody>${demoPatients.map(p=>{const r=state.patientRecords[p.id];return `<tr><td><time>${p.time}</time></td><td><button class="patient-name" onclick="openPatient('${p.id}')"><span class="avatar">${p.initials}</span><span><strong>${p.name}</strong><small>${p.id}</small></span></button></td><td>${p.visit}</td><td><span class="pill ${r.signed?'green':r.note?'amber':'grey'}">${r.signed?'Reviewed locally':r.note?'Draft':'Not started'}</span></td><td><button class="table-action" onclick="openPatient('${p.id}','C')" aria-label="Open consultation for ${p.name}">${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h2>Continue your work</h2><p>Your most recent local documents.</p></div><button class="text-btn" onclick="nav('documents')">View documents ${icon('arrow')}</button></div>${docs.length?docs.slice(0,3).map(d=>documentListItem(d)).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('file')}</span><h3>No documents started</h3><p>Open a patient’s consultation to prepare the first draft.</p><button onclick="chooseConsultation()">Choose a patient</button></div>`}</div></section><aside><div class="panel focus-panel"><span class="eyebrow">NEXT ACTION</span><h2>${pendingReviewCount()?'Review before sharing':'Prepare for the next appointment'}</h2><p>${pendingReviewCount()?pendingReviewCount()+' document or form items need review.':'Open the patient context, check the available source information and record consent before capture.'}</p><button class="primary wide" onclick="${pendingReviewCount()?"nav('review')":"openPatient('DEMO-001','E')"}">${pendingReviewCount()?'Open review queue':'Open Maya’s briefing'} ${icon('arrow')}</button></div><div class="panel"><div class="panel-head"><h2>Team tasks</h2><span class="pill grey">${openTasks.length} open</span></div>${openTasks.slice(0,3).map(t=>`<button class="compact-task" onclick="nav('T')"><span class="task-circle"></span><span><strong>${esc(t.text)}</strong><small>${esc(t.owner)}</small></span></button>`).join('')||'<p class="fine">No open tasks.</p>'}<button class="text-btn" onclick="nav('T')">Open task board ${icon('arrow')}</button></div><div class="workspace-connection"><span class="status-dot"></span><div><strong>Clinical OS connection pending</strong><p>Records are synthetic and saved in this browser.</p><button class="text-btn" onclick="nav('connections')">Connection details</button></div></div></aside></div>`;};
function chooseConsultation(target='C'){if(!['record','C','N','F','E','I'].includes(target))target='C';modal(target==='C'?'Start a consultation':'Change active patient',`<p>Select the patient before starting. These are synthetic records.</p>${demoPatients.map(p=>`<button class="patient-option" onclick="closeModal();openPatient('${p.id}','${target}')"><span class="avatar">${p.initials}</span><span><strong>${p.name}</strong><small>${p.id} · ${p.time} · ${p.visit}</small></span>${icon('arrow')}</button>`).join('')}`);}
function filteredPatients(){const q=patientQuery.trim().toLowerCase();return demoPatients.filter(p=>[p.name,p.id,p.visit].some(v=>v.toLowerCase().includes(q)));}
patientPage=function(){return pageHeading('Patients','Find a patient, prepare for the appointment and continue their documentation.')+`<div class="panel directory-panel"><div class="directory-toolbar"><label class="search-field" for="patient-search"><span class="sr-only">Search patients by name or record ID</span>${icon('search')}<input id="patient-search" type="search" placeholder="Search by name or record ID" value="${esc(patientQuery)}" oninput="patientQuery=this.value;renderPatientDirectory()"></label><span class="pill grey">Synthetic records · ${demoPatients.length}</span></div><div id="patient-directory-results">${patientDirectoryRows()}</div></div>`;};
function patientDirectoryRows(){const patients=filteredPatients();return `<p class="result-count" role="status">${patients.length} ${patients.length===1?'patient':'patients'}</p>${patients.length?`<div class="patient-card-grid">${patients.map(p=>{const r=state.patientRecords[p.id];return `<article class="patient-card"><div class="patient-card-head"><span class="avatar">${p.initials}</span><div><h2>${p.name}</h2><span class="record-id">${p.id}</span></div><span class="pill grey">Synthetic</span></div><dl><dt>Appointment</dt><dd>${p.time} · ${p.visit}</dd><dt>Patient priority</dt><dd>${p.priority}</dd><dt>Document</dt><dd>${r.signed?'Reviewed locally':r.note?'Draft awaiting review':'Not started'}</dd></dl><div class="actions"><button class="primary" onclick="openPatient('${p.id}')">Open record ${icon('arrow')}</button><button onclick="openPatient('${p.id}','C')">Consultation</button></div></article>`}).join('')}</div>`:`<div class="workspace-empty"><h3>No matching patients</h3><p>Try a name such as Maya or a record ID such as DEMO-001.</p><button onclick="patientQuery='';nav('patients')">Clear search</button></div>`}`;}
function renderPatientDirectory(){document.getElementById('patient-directory-results').innerHTML=patientDirectoryRows();}
patientDetail=function(name){const p=demoPatients.find(p=>p.name===name);if(p)openPatient(p.id);};
patientStrip=function(){const p=currentPatient();return `<section class="patient-context-bar" aria-label="Active patient"><div class="context-identity"><span class="avatar">${p.initials}</span><div><button class="context-name" onclick="nav('record')">${p.name}</button><p>${p.id} <span>·</span> Synthetic record</p></div></div><div class="patient-checks"><span><strong>Date of birth</strong>Not supplied</span><span><strong>NHS number</strong>Not supplied</span><span class="missing-context"><strong>Allergies</strong>Not recorded</span></div><button class="patient-switch" onclick="chooseConsultation(route)" aria-label="Change active patient">Change patient ${icon('people')}</button></section>`;};
function patientWorkspaceTabs(){return `<nav class="patient-tabs" aria-label="Patient workspace">${[['record','Overview'],['C','Consultation'],['N','Note'],['F','Forms'],['E','Context'],['I','Handoff']].map(([id,label])=>`<button ${route===id?'aria-current="page"':''} class="${route===id?'active':''}" onclick="nav('${id}')">${label}</button>`).join('')}</nav>`;}
function recordPage(){const p=currentPatient();const r=state.patientRecords[p.id];return pageHeading('Patient workspace',p.visit,`<button class="primary" onclick="nav('C')">${icon('mic')} Open consultation</button>`)+patientStrip()+patientWorkspaceTabs()+`<div class="workspace-grid"><section><div class="panel"><div class="panel-head"><h2>At a glance</h2><span class="pill grey">Patient-stated context</span></div><div class="context-section"><span class="eyebrow">PATIENT PRIORITY</span><h3>${p.priority}</h3><p>${p.source}</p></div><div class="context-section"><span class="eyebrow">FOLLOW-UP PREFERENCE</span><h3>${p.preference}</h3><p>${p.action}.</p></div><div class="notice amber">Medication and allergies have not been supplied. Verify with the patient and the authorised record before clinical use.</div></div><div class="panel"><div class="panel-head"><h2>Documentation</h2><button class="text-btn" onclick="nav('N')">Open editor ${icon('arrow')}</button></div>${r.note?documentListItem({patient:p,record:r}):'<p class="fine">No document has been started for this patient.</p>'}<div class="record-status-grid"><div><span>Recording consent</span><strong>${r.consent?'Recorded locally':'Not recorded'}</strong></div><div><span>Follow-up form</span><strong>${r.formApproval?'Approved locally':r.formData?'Awaiting review':'Not started'}</strong></div></div></div></section><aside><div class="panel"><h2>Appointment</h2><div class="appointment-summary"><strong>${p.time}</strong><span>13 October 2026<br>Example clinic</span></div><p>${p.visit}</p><button class="wide" onclick="nav('E')">Open pre-appointment briefing</button></div><div class="panel"><h2>Record sources</h2><p class="fine">Scripted patient context and conversation only. No external clinical records have been retrieved.</p><button class="wide" onclick="modal('Conversation source',transcriptMarkup())">Read conversation source</button></div></aside></div>`;}
function documentListItem({patient:p,record:r}){return `<button class="document-list-item" onclick="openPatient('${p.id}','N')"><span class="document-symbol">${icon('file')}</span><span><strong>${p.name}</strong><small>${r.noteTemplate==='soap'?'Consultation note':r.noteTemplate==='referral'?'Referral letter':r.noteTemplate==='summary'?'Patient summary':'MDT handover'} · Version ${r.version}</small></span><span class="pill ${r.signed?'green':'amber'}">${r.signed?'Reviewed locally':'Draft'}</span>${icon('arrow')}</button>`;}
function documentsPage(){const all=allDocumentRows();const rows=all.filter(d=>documentFilter==='all'||(documentFilter==='signed'?d.record.signed:!d.record.signed));return pageHeading('Documents','Continue drafts, review source material and track reviewed versions.',`<button class="primary" onclick="chooseConsultation('N')">${icon('plus')} Create document</button>`)+`<div class="segmented" aria-label="Filter documents">${[['all','All documents',all.length],['draft','Drafts',all.filter(d=>!d.record.signed).length],['signed','Reviewed',all.filter(d=>d.record.signed).length]].map(([key,label,total])=>`<button aria-pressed="${documentFilter===key}" onclick="documentFilter='${key}';render()">${label}<span>${total}</span></button>`).join('')}</div><div class="panel">${rows.length?rows.map(documentListItem).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('file')}</span><h2>${documentFilter==='signed'?'No reviewed documents yet':documentFilter==='draft'?'No drafts to continue':'Your document workspace is ready'}</h2><p>${documentFilter==='signed'?'Reviewed versions will appear here after the note review step.':'Choose a patient to begin a consultation note or letter.'}</p><button onclick="chooseConsultation()">Choose a patient</button></div>`}</div>`;}
function reviewPage(){const items=demoPatients.flatMap(p=>{const r=state.patientRecords[p.id];return [...(r.note.trim()&&!r.signed?[{p,type:'Document',title:'Consultation document',to:'N',detail:'Version '+r.version+' · Review against the source'}]:[]),...(r.formData&&!r.formApproval?[{p,type:'Form',title:'Follow-up preference form',to:'F',detail:r.formData.filter(f=>f.reviewed).length+' of '+r.formData.length+' fields reviewed'}]:[])];});return pageHeading('Review queue','Review each item against its source before approval or sharing.')+`<div class="review-summary"><span class="review-number">${items.length}</span><div><h2>${items.length===1?'item needs':'items need'} review</h2><p>Across the fictional workspace. No documents have been sent to an EPR.</p></div><span class="pill grey">Human review required</span></div><div class="panel">${items.length?items.map(i=>`<div class="review-row"><span class="document-symbol">${icon(i.type==='Form'?'form':'file')}</span><div><h3>${i.p.name} <span class="pill grey">${i.type}</span></h3><p>${i.title} · ${i.detail}</p></div><button class="primary" onclick="openPatient('${i.p.id}','${i.to}')">Review ${icon('arrow')}</button></div>`).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('check')}</span><h2>Nothing is waiting for review</h2><p>Unsigned notes and unapproved forms will appear here as you work.</p><button onclick="nav('documents')">Open documents</button></div>`}</div>`;}
const uiWorkflowFunctions={C:consultation,N:notes,F:forms,E:evidence,I:integrations};
categoryPage=function(key){if(uiWorkflowFunctions[key])return pageHeading(workspaceLabels[key],{C:'Capture the conversation, confirm the source and prepare a draft.',N:'Write, compare with the source and review the exact version.',F:'Keep source information visible while completing and reviewing forms.',E:'Review the available information before the consultation.',I:'Track the document from review to confirmed receipt.'}[key])+patientStrip()+patientWorkspaceTabs()+uiWorkflowFunctions[key]().replace(patientStrip(),'');if(key==='T')return tasks();if(key==='NHS')return pageHeading('Governance & assurance','Evidence, accountable owners and deployment decisions.')+governance();if(key==='DS')return extensionsPage();return home();};
// New editor layout delegates mutations and signing to the existing workflow module.
uiWorkflowFunctions.N=function(){return patientStrip()+`<div class="document-workspace"><section class="panel note-panel"><div class="panel-head"><div><h2>Clinical document</h2><p>Version ${state.version} · ${state.signed?'Reviewed locally':'Saved as you type in this browser'}</p></div><span class="pill ${state.signed?'green':'amber'}">${state.signed?'Reviewed':'Draft'}</span></div><div class="editor-template"><label for="note-template">Template</label><select id="note-template" class="field" ${state.signed?'disabled':''} onchange="changeTemplate(this.value)">${[['soap','SOAP consultation note'],['referral','Referral letter'],['summary','Patient-friendly summary'],['mdt','MDT handover']].map(([id,label])=>`<option value="${id}" ${state.noteTemplate===id?'selected':''}>${label}</option>`).join('')}</select><button ${state.signed?'disabled':''} onclick="draftNote()">Load example</button></div><label class="editor-label" for="note-text">Document text <span>Synthetic information only</span></label><textarea class="field note-editor" id="note-text" ${state.signed?'readonly':''} placeholder="Begin writing, or load an example to explore the workflow." oninput="updateNote(this.value)">${esc(state.note)}</textarea><div class="editor-actionbar"><button onclick="showHistory()">${icon('clock')} Version history</button><button onclick="exportNote()">${icon('download')} Export</button>${state.signed?'<button class="primary" onclick="amendNote()">Create amendment</button>':'<button onclick="saveNote()">Save draft version</button><button class="primary" onclick="reviewNote()">Review & sign</button>'}</div><p class="fine">Local workflow only. A recorded review here is not a clinical signature or an EPR submission.</p></section><aside><section class="panel source-panel"><div class="panel-head"><h2>Source conversation</h2><span class="pill grey">Scripted</span></div>${transcriptMarkup()}</section><section class="panel"><h2>After review</h2><p class="fine">Create a task linked to the signed version, or inspect the EPR handoff.</p><button class="wide" ${!state.signed?'disabled':''} onclick="createFollowup()">Create follow-up task</button><button class="wide" onclick="nav('I')">Open handoff</button></section></aside></div>`;};
function filteredTasks(){return state.tasks.map((t,index)=>({...t,index})).filter(t=>(taskFilter==='all'||(taskFilter==='done'?t.done:!t.done))&&(taskOwner==='all'||t.owner===taskOwner));}
tasks=function(){const rows=filteredTasks();return pageHeading('Tasks & handovers','Keep ownership clear and follow-up connected to the source.',`<button class="primary" onclick="openTaskComposer()">${icon('plus')} Add task</button>`)+`<div class="task-toolbar"><div class="segmented" aria-label="Filter task status">${[['open','Open'],['done','Completed'],['all','All tasks']].map(([id,label])=>`<button aria-pressed="${taskFilter===id}" onclick="taskFilter='${id}';render()">${label}</button>`).join('')}</div><label for="task-owner-filter">Assigned to <select class="field" id="task-owner-filter" onchange="taskOwner=this.value;render()">${[['all','Everyone'],['Dr Morgan','Dr Morgan'],['Care team','Care team'],['Admin team','Admin team']].map(([id,label])=>`<option value="${id}" ${taskOwner===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="panel"><div class="panel-head"><h2>${rows.length} ${rows.length===1?'task':'tasks'}</h2><span class="fine">Stored in this browser</span></div>${rows.length?rows.map(t=>`<div class="work-task ${t.done?'done':''}"><input type="checkbox" aria-label="Mark ${esc(t.text)} ${t.done?'open':'complete'}" ${t.done?'checked':''} onchange="setTaskDone(${t.index},this.checked)"><div class="work-task-main"><strong>${esc(t.text)}</strong><small>${t.patientId?esc(demoPatients.find(p=>p.id===t.patientId)?.name||t.patientId):'Team administration'}${t.sourceKey?' · Linked to reviewed note':''}</small></div><select class="field" aria-label="Assign ${esc(t.text)}" onchange="setTaskOwner(${t.index},this.value)">${['Dr Morgan','Care team','Admin team'].map(owner=>`<option ${t.owner===owner?'selected':''}>${owner}</option>`).join('')}</select>${t.sourceNote?`<button onclick="showTaskSource(${t.index})">View source</button>`:''}</div>`).join(''):'<div class="workspace-empty"><h3>No tasks match these filters</h3><p>Change the status or assignee to see more work.</p><button onclick="taskFilter=\'all\';taskOwner=\'all\';render()">Show all tasks</button></div>'}</div>`;};
function setTaskDone(index,done){if(!state.tasks[index])return;state.tasks[index].done=done;audit('Local task '+(done?'completed':'reopened')+': '+state.tasks[index].text);render();}
function setTaskOwner(index,owner){if(!state.tasks[index]||!['Dr Morgan','Care team','Admin team'].includes(owner))return;state.tasks[index].owner=owner;audit('Local task assigned to '+owner+'.');render();toast('Assignment saved in this workspace.');}
function showTaskSource(index){const t=state.tasks[index];if(!t?.sourceNote)return;modal('Reviewed source for task',`<p>${esc(t.sourceKey)}</p><pre class="review-copy">${esc(t.sourceNote)}</pre><p class="fine">This is the exact local note snapshot linked when the task was created.</p>`);}
function openTaskComposer(){modal('Add a team task',`<form id="task-composer" onsubmit="event.preventDefault();saveComposedTask(this)"><div class="form-group"><label for="task-description">Task description</label><input class="field" id="task-description" name="description" maxlength="150" required placeholder="Use fictional information only"></div><div class="form-group"><label for="task-assignee">Assign to</label><select class="field" id="task-assignee" name="owner">${['Care team','Dr Morgan','Admin team'].map(o=>`<option>${o}</option>`).join('')}</select></div><p class="fine">Saved locally. No message or external task is sent.</p></form>`,`<button onclick="closeModal()">Cancel</button><button type="submit" form="task-composer" class="primary">Save task</button>`);document.getElementById('task-description')?.focus?.();}
function saveComposedTask(form){const text=form.description.value.trim();const owner=form.owner.value;if(!text||text.length>150||!['Care team','Dr Morgan','Admin team'].includes(owner))return;state.tasks.push({text,owner,done:false});audit('Local team task added.');closeModal();taskFilter='open';taskOwner='all';nav('T');toast('Task saved in this workspace.');}
settingsPage=function(){return pageHeading('Settings','Workspace preferences, organisation setup and connected services.')+`<div class="settings-grid">${[['organisation','people','Organisation','Service, team and workspace configuration.'],['connections','link','Connections','Clinical OS, identity and EPR setup.'],['NHS','shield','Governance','Assurance evidence and deployment decisions.'],['extensions','spark','Extensions','Optional DeepSynaps services and request drafts.']].map(([id,symbol,title,description])=>`<button class="settings-card" onclick="nav('${id}')"><span class="card-icon">${icon(symbol)}</span><span><strong>${title}</strong><small>${description}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="panel"><h2>Appearance</h2><div class="toggle-row"><div><strong>Colour theme</strong><p>${state.product.theme==='dark'?'Dark':'Light'} workspace · Saved in this browser</p></div><button onclick="toggleTheme()">Use ${state.product.theme==='dark'?'light':'dark'} theme</button></div></div><details class="panel advanced-settings"><summary>Development workspace & capability reference</summary><p class="fine">This build uses synthetic records. These controls affect local examples only.</p><div class="actions"><button onclick="nav('catalogue')">158-function library</button><button onclick="nav('delivery')">Delivery plan</button><button onclick="nav('loops')">Implementation loops</button><button onclick="showAbout()">Source & scope</button></div>${[['ai','Example note drafting'],['speech','Example transcription'],['sms','Example SMS preview']].map(([id,label])=>`<div class="toggle-row"><strong>${label}</strong><button class="switch" role="switch" aria-label="${label}" aria-checked="${state.settings[id]}" onclick="state.settings.${id}=!state.settings.${id};save();render()"></button></div>`).join('')}<button class="reset-workspace" onclick="confirmReset()">Reset synthetic workspace</button></details>`;};
function workspaceSearchResults(query){const q=query.trim().toLowerCase();const patients=demoPatients.filter(p=>[p.name,p.id].some(v=>v.toLowerCase().includes(q)));const pages=Object.entries(workspaceLabels).filter(([id,label])=>!['record','N','delivery','loops'].includes(id)&&label.toLowerCase().includes(q));return `<h3>Patients</h3>${patients.map(p=>`<button class="search-result" onclick="closeModal();openPatient('${p.id}')">${icon('people')}<span><strong>${p.name}</strong><small>${p.id} · ${p.visit}</small></span>${icon('arrow')}</button>`).join('')||'<p class="fine">No matching patient.</p>'}<h3>Workspace</h3>${pages.slice(0,7).map(([id,label])=>`<button class="search-result" onclick="closeModal();nav('${id}')">${icon('grid')}<span>${label}</span>${icon('arrow')}</button>`).join('')||'<p class="fine">No matching workspace.</p>'}`;}
function openWorkspaceSearch(){closeWorkspaceNavigation(false);modal('Find in your workspace',`<label class="sr-only" for="workspace-query">Search patients and workspaces</label><input class="field command-input" id="workspace-query" type="search" placeholder="Search patients, record IDs or workspaces" oninput="document.getElementById('workspace-search-results').innerHTML=workspaceSearchResults(this.value)"><div class="workspace-search-results" id="workspace-search-results">${workspaceSearchResults('')}</div>`);document.getElementById('workspace-query')?.focus?.();}
const previousProductUiRender=render;
render=function(){previousProductUiRender();document.documentElement.dataset.workspaceUi='product';const pages={record:recordPage,documents:documentsPage,review:reviewPage};if(pages[route])document.getElementById('main').innerHTML=pages[route]();document.getElementById('topbar').innerHTML=workspaceTopbar();document.title=(workspaceLabels[route]||'Workspace')+' | DeepSynaps Clinical Admin';syncWorkspaceNavigation();};
document.addEventListener?.('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openWorkspaceSearch();}if(event.key==='Escape'&&mobileNavigationOpen){event.preventDefault();closeWorkspaceNavigation();}handleWorkspaceNavigationKey(event);});
const uiInitialRoute=location.hash.slice(1);if(Object.hasOwn(workspaceLabels,uiInitialRoute))route=uiInitialRoute;
render();
// Workspace routes added here must also resolve through hash links and browser history.
window.addEventListener?.('hashchange',()=>{const target=location.hash.slice(1)||'home';if(Object.hasOwn(workspaceLabels,target)&&target!==route)nav(target);});

// Off-canvas navigation is modal on small screens, including keyboard access.
function syncWorkspaceNavigation(){
 const mobile=!!workspaceMobileQuery?.matches;
 if(!mobile)mobileNavigationOpen=false;
 const open=mobile&&mobileNavigationOpen;
 const sidebar=document.getElementById('sidebar');
 sidebar.classList.toggle('open',open);
 sidebar.inert=mobile&&!open;
 sidebar.setAttribute?.('aria-label',open?'Workspace navigation':'Workspace sidebar');
 if(open){sidebar.setAttribute?.('role','dialog');sidebar.setAttribute?.('aria-modal','true');}
 else{sidebar.removeAttribute?.('role');sidebar.removeAttribute?.('aria-modal');}
 const shell=document.querySelector?.('.shell');if(shell)shell.inert=open;
 const backdrop=document.getElementById('navigation-backdrop');if(backdrop)backdrop.hidden=!open;
 document.getElementById('navigation-toggle')?.setAttribute?.('aria-expanded',String(open));
 document.documentElement.classList?.toggle('navigation-open',open);
}
function openWorkspaceNavigation(){
 if(!workspaceMobileQuery?.matches)return;
 mobileNavigationOpen=true;syncWorkspaceNavigation();
 document.querySelector?.('.navigation-close')?.focus();
}
function closeWorkspaceNavigation(restoreFocus=true){
 const wasOpen=mobileNavigationOpen;mobileNavigationOpen=false;syncWorkspaceNavigation();
 if(wasOpen&&restoreFocus)document.getElementById('navigation-toggle')?.focus();
}
const navigateWorkspace=nav;
nav=function(to){closeWorkspaceNavigation(false);navigateWorkspace(to);};
workspaceMobileQuery?.addEventListener?.('change',()=>{const wasOpen=mobileNavigationOpen;syncWorkspaceNavigation();if(wasOpen&&!workspaceMobileQuery.matches)document.querySelector?.('#sidebar [aria-current="page"]')?.focus();});
function handleWorkspaceNavigationKey(event){
 if(!mobileNavigationOpen||event.key!=='Tab'||document.getElementById('dialog').open)return;
 const controls=Array.from(document.getElementById('sidebar').querySelectorAll('a[href],button:not([disabled])'));
 const first=controls[0],last=controls.at(-1);
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
}
